server_scripts.script:
from collections import defaultdict

# Ported verbatim from onefm_mcp's sitrep_agent_data_collector.py (WI-002201).
SECURITY_KEYWORDS = {
	"security", "crime", "robbery", "cyber", "terrorism", "theft", "attack",
	"breach", "exploit", "malware", "emergency", "phishing", "hacking",
	"fraud", "scam", "violence", "assault", "murder", "kidnapping", "hostage", "public safety",
}
ENVIRONMENTAL_KEYWORDS = {
	"environmental", "weather", "natural disaster", "earthquake", "flood",
	"hurricane", "tornado", "drought", "wildfire", "tsunami", "dust storm",
	"storm", "climate", "pollution", "contamination", "fog", "heat wave", "fire",
}


def _categorize(keywords_found):
	if not keywords_found:
		return "security"
	keyword_strings = [k.lower() for k in keywords_found if k]
	security_matches = sum(1 for k in keyword_strings if k in SECURITY_KEYWORDS)
	environmental_matches = sum(1 for k in keyword_strings if k in ENVIRONMENTAL_KEYWORDS)
	return "environmental" if environmental_matches > security_matches else "security"


report_name = task_data.get("report_name")

try:
	threats = frappe.get_all(
		"Threat Feed",
		filters={
			"collected_date": ["between", [task_data.get("data_period_start"), task_data.get("data_period_end")]],
			"docstatus": ["<", 2],
		},
		fields=["name", "source", "collected_date", "content"],
	)
	# Datetime fields must not cross the workflow-state JSON boundary as objects.
	for t in threats:
		if t.get("collected_date"):
			t["collected_date"] = str(t["collected_date"])

	threat_names = [t["name"] for t in threats]
	keywords_by_threat = defaultdict(list)
	if threat_names:
		for kw in frappe.get_all(
			"Threat Feed Keyword",
			filters={"parent": ["in", threat_names]},
			fields=["parent", "keyword.keyword"],
		):
			keywords_by_threat[kw.parent].append(kw.keyword)

	security_threats = []
	environmental_threats = []
	for threat in threats:
		category = _categorize(keywords_by_threat.get(threat["name"], []))
		threat["category"] = category
		(security_threats if category == "security" else environmental_threats).append(dict(threat))

	total_count = len(threats)

	if report_name:
		frappe.db.set_value("Threat Assessment Report", report_name, {
			"total_threats": total_count,
			"security_threats_count": len(security_threats),
			"environmental_threats_count": len(environmental_threats),
		})
		frappe.db.commit()

	result["threat_data"] = {"security": security_threats, "environmental": environmental_threats, "total_count": total_count}
	result["security_count"] = len(security_threats)
	result["environmental_count"] = len(environmental_threats)
	result["threat_count"] = total_count
	result["generation_status"] = "OK"
except Exception:
	error_msg = "Error in data collection: " + frappe.get_traceback()
	frappe.log_error(title="SITREP Data Collection Error", message=error_msg)
	if report_name:
		frappe.db.set_value("Threat Assessment Report", report_name, {
			"generation_status": "Failed",
			"error_log": error_msg[:9000],
		})
		frappe.db.commit()
	result["generation_status"] = "Failed"
	result["threat_count"] = 0
	result["threat_data"] = {"security": [], "environmental": [], "total_count": 0}
	result["security_count"] = 0
	result["environmental_count"] = 0
